import type { IncomingMessage, ServerResponse } from 'http';
// Load the esbuild bundle, not the TypeScript source tree. Unbundled firebase-admin
// pulls jwks-rsa which require()s ESM-only jose and crashes Node 22 (ERR_REQUIRE_ESM).
// @ts-ignore — generated by `npm run build`
import { handleCoreApi } from '../core-server.bundle.js';

export const config = { api: { bodyParser: false } };

async function readRaw(req: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const chunk of req) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
  return Buffer.concat(chunks);
}

export default async function handler(req: IncomingMessage & { body?: any }, res: ServerResponse) {
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Allow', 'GET, HEAD, POST, OPTIONS');
  if (req.method === 'OPTIONS') {
    res.statusCode = 204;
    return res.end();
  }
  // Browser / Vercel / Resend URL checks use GET. Real events are POST.
  if (req.method === 'GET' || req.method === 'HEAD') {
    res.statusCode = 200;
    return res.end(JSON.stringify({ ok: true, webhook: 'resend', hint: 'Resend should POST email.opened / email.clicked here' }));
  }
  if (req.method !== 'POST') {
    res.statusCode = 405;
    return res.end(JSON.stringify({ error: 'POST only' }));
  }
  try {
    const raw = await readRaw(req);
    try {
      req.body = JSON.parse(raw.toString('utf8') || '{}');
    } catch {
      req.body = {};
    }
    // Dedicated function URL is /api/webhooks/resend; the bundled router matches the public path.
    req.url = '/api/webhooks/email/resend';
    const handled = await handleCoreApi(req, res);
    if (!handled && !res.writableEnded) {
      res.statusCode = 200;
      res.end(JSON.stringify({ received: true }));
    }
  } catch (err: any) {
    console.error('[Resend webhook error]:', err);
    if (!res.writableEnded) {
      res.statusCode = 500;
      res.end(JSON.stringify({ error: 'webhook handler failed' }));
    }
  }
}
